svg.appendChild(el("line", {x1:xp(eventIdx23), x2:xp(eventIdx23), y1:margin.top, y2:margin.top+PH, stroke:"#1a3560", "stroke-width":"1", opacity:"0.5", "stroke-dasharray":"2,3"}));
